$$\begin{array}{cll}
  {h(a)} & = & {f(a) - f(a) - \frac{f(b) - f(a)}{b - a}\left( {a - a} \right) = 0} \\
  {h(b)} & = & {f(b) - f(a) - \frac{f(b) - f(a)}{b - a}\left( {b - a} \right)} \\
   & = & {f(b) - f(a) - \left\lbrack {f(b) - f(a)} \right\rbrack = 0}
  \end{array}$$

$$\begin{array}{l}
  {{\lim\limits_{x\rightarrow a}\frac{f^{\prime}(x)}{g^{\prime}(x)}} = {\frac{f^{\prime}(a)}{g^{\prime}(a)} = \frac{\lim\limits_{x\rightarrow a}\frac{f{(x)} - f{(a)}}{x - a}}{\lim\limits_{x\rightarrow a}\frac{g{(x)} - g{(a)}}{x - a}}}} \\
  {\phantom{\lim\limits_{x\rightarrow a}\frac{f^{\prime}(x)}{g^{\prime}(x)}} = \lim\limits_{x\rightarrow a}\frac{\frac{f{(x)} - f{(a)}}{x - a}}{\frac{g{(x)} - g{(a)}}{x - a}}} \\
  {\phantom{\lim\limits_{x\rightarrow a}\frac{f^{\prime}(x)}{g^{\prime}(x)}} = {\lim\limits_{x\rightarrow a}\frac{f(x) - f(a)}{g(x) - g(a)} = \lim\limits_{x\rightarrow a}\frac{f(x)}{g(x)}\qquad\left\lbrack {{because}f(a) = g(a) = 0} \right\rbrack}}
  \end{array}$$

$$\begin{array}{l}
  {{\lim\limits_{x\rightarrow 0}\frac{\tan x - x}{x^{3}}} = {\lim\limits_{x\rightarrow 0}\frac{\sec^{2}x - 1}{3x^{2}} = \lim\limits_{x\rightarrow 0}\frac{2\sec^{2}x\tan x}{6x}}} \\
  {\phantom{\lim\limits_{x\rightarrow 0}\frac{\tan x - x}{x^{3}}} = {\frac{1}{3}\lim\limits_{x\rightarrow 0}\frac{\tan x}{x} = \frac{1}{3}\lim\limits_{x\rightarrow 0}\frac{\sec^{2}x}{1} = \frac{1}{3}}}
  \end{array}$$

$$\begin{array}{l}
  {{\lim\limits_{x\rightarrow 1^{+}}\frac{x - 1}{x - 1 + x\ln x}} = {\lim\limits_{x\rightarrow 1^{+}}\frac{1}{1 + x \cdot \frac{1}{x} + \ln x}}} \\
  {\phantom{\lim\limits_{x\rightarrow 1^{+}}\frac{x - 1}{x - 1 + x\ln x}} = {\lim\limits_{x\rightarrow 1^{+}}\frac{1}{2 + \ln x} = \frac{1}{2}}}
  \end{array}$$

$$\begin{array}{ll}
  {{Intervals\ of\ increase}:} & {\left( {0,0.6} \right),\left( {1.0,1.6} \right),\left( {2.1,2.5} \right)} \\
  {{Intervals\ of\ decrease}:} & {\left( {0.6,1.0} \right),\left( {1.6,2.1} \right),\left( {2.5,\pi} \right)} \\
  {{Local\ maximum\ values}:} & {f(0.6) \approx 1,f(1.6) \approx 1,f(2.5) \approx 1} \\
  {{Local\ minimum\ values}:} & {f(1.0) \approx 0.94,f(2.1) \approx 0.94}
  \end{array}$$
